  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface ReservationRequest {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export interface Reservation extends ReservationRequest {
  id: number;
}

export interface BookingForm {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  paid: boolean;
  customerEmail: string | null;
  form: BookingForm;
}

export function emptyBookingForm(): BookingForm {
  return {
    firstName: '',
    lastName: '',
    email: '',
    confirmEmail: '',
    phone: '',
    terms: false,
  };
}

export function emptyBooking(screeningId: number): Booking {
  return {
    screeningId,
    seats: [],
    paid: false,
    customerEmail: null,
    form: emptyBookingForm(),
  };
