function requiredValidator(): ValidatorFn {
  return (control) => {
    const value = control.value;
    return value === null || value === undefined || value === '' ? { required: true } : null;
  };
}

function requiredTrueValidator(): ValidatorFn {
  return (control) => (control.value === true ? null : { required: true });
}

function minLengthValidator(min: number): ValidatorFn {
  return (control) => {
    const value: string = control.value ?? '';
    if (value.length === 0) return null;
    return value.length >= min ? null : { minlength: { requiredLength: min, actualLength: value.length } };
  };
}

