    effect(() => {
      const id = this.screeningId();
      this.screening.set(null);
      this.movie.set(null);

      if (!Number.isFinite(id)) {
        this.router.navigateByUrl('/');
        return;
      }

      this.api.getScreening(id).subscribe({
        next: (screening) => {
          this.api.getMovie(screening.movieId).subscribe({
            next: (movie) => {
