export interface Movie {
  id: number;
  title: string;
  genre: string;
  runtimeMinutes: number;
  format: 'PL dubbing' | 'PL subtitles';
}

export interface Screening {
  id: number;
  movieId: number;
  date: string;
  time: string;
  occupiedSeats: string[];
}

export interface ReservationCustomer {
  firstName: string;
  lastName: string;
  email: string;
  phone: string;
}

export interface ReservationRequest {
  screeningId: number;
  seats: string[];
  customer: ReservationCustomer;
  totalPrice: number;
}

export interface Reservation extends ReservationRequest {
  id: number;
}

export interface BookingForm {
  firstName: string;
  lastName: string;
  email: string;
  confirmEmail: string;
  phone: string;
  terms: boolean;
}

export interface Booking {
  screeningId: number;
  seats: string[];
  paid: boolean;
  customerEmail: string | null;
  form: BookingForm;
}

export function emptyBookingForm(): BookingForm {
  return {
    firstName: '',
    lastName: '',
    email: '',
    confirmEmail: '',
    phone: '',
    terms: false,
  };
}

export function emptyBooking(screeningId: number): Booking {
  return {
    screeningId,
    seats: [],
    paid: false,
    customerEmail: null,
    form: emptyBookingForm(),
  };
}

export type SeatState = 'available' | 'selected' | 'unavailable' | 'accessible';

export const TOTAL_ROWS = 15;
export const COUCH_ROW = 15;
export const ACCESSIBLE_ROW = 1;
export const ACCESSIBLE_COLUMNS: readonly number[] = [10, 11, 12, 13, 14, 15];
export const MAX_SEATS_PER_BOOKING = 10;
export const COUCH_PRICE = 89;

export function seatId(row: number, column: number): string {
  return `R${row}C${column}`;
}

export function parseSeatId(id: string): { row: number; column: number } {
  const match = /^R(\d+)C(\d+)$/.exec(id);
  if (!match) {
    throw new Error(`Invalid seat id: ${id}`);
  }
  return { row: Number(match[1]), column: Number(match[2]) };
}

export function isAccessible(row: number, column: number): boolean {
  return row === ACCESSIBLE_ROW && ACCESSIBLE_COLUMNS.includes(column);
}

/** The 12 couch column pairs of row 15: [1,2], [3,4] … [23,24]. */
export function couchPairs(): Array<[number, number]> {
  const pairs: Array<[number, number]> = [];
  for (let start = 1; start <= 23; start += 2) {
    pairs.push([start, start + 1]);
  }
  return pairs;
}

export function couchPairFor(column: number): [number, number] {
  const start = column % 2 === 1 ? column : column - 1;
  return [start, start + 1];
}

export function seatPrice(row: number): number {
  if (row >= 1 && row <= 5) return 25;
  if (row >= 6 && row <= 10) return 32;
  if (row >= 11 && row <= 14) return 39;
  throw new Error(`Row ${row} has no single-seat price`);
}

export function formatPrice(amount: number): string {
  return `${amount.toFixed(2)} PLN`;
}

export function seatState(
  id: string,
  occupied: ReadonlySet<string>,
  selected: ReadonlySet<string>,
  accessible: boolean,
): SeatState {
  if (selected.has(id)) return 'selected';
  if (occupied.has(id)) return 'unavailable';
  return accessible ? 'accessible' : 'available';
}

export function couchState(
  id1: string,
  id2: string,
  occupied: ReadonlySet<string>,
  selected: ReadonlySet<string>,
): SeatState {
  if (selected.has(id1) || selected.has(id2)) return 'selected';
  if (occupied.has(id1) || occupied.has(id2)) return 'unavailable';
  return 'available';
}

export interface SummaryEntry {
  row: number;
  kind: 'seat' | 'couch';
  seatLabel: string;
  identifiers: string[];
  price: number;
}

/** Groups raw seat identifiers into seat/couch entries, ordered by row then column. */
export function buildSummaryEntries(seats: readonly string[]): SummaryEntry[] {
  const parsed = seats.map((id) => ({ id, ...parseSeatId(id) }));
  parsed.sort((a, b) => a.row - b.row || a.column - b.column);

  const seen = new Set<string>();
  const entries: SummaryEntry[] = [];

  for (const { id, row, column } of parsed) {
    if (seen.has(id)) continue;
    if (row === COUCH_ROW) {
      const [start, end] = couchPairFor(column);
      const id1 = seatId(row, start);
      const id2 = seatId(row, end);
      seen.add(id1);
      seen.add(id2);
      entries.push({
        row,
        kind: 'couch',
        seatLabel: `Couch ${start}-${end}`,
        identifiers: [id1, id2],
        price: COUCH_PRICE,
      });
    } else {
      seen.add(id);
      entries.push({
        row,
        kind: 'seat',
        seatLabel: String(column),
        identifiers: [id],
        price: seatPrice(row),
      });
    }
  }

  return entries;
}

export interface RowSelectionLine {
  row: number;
  text: string;
}

/** Groups selected seat identifiers into one display line per row, columns ascending. */
export function buildRowSelectionLines(seats: readonly string[]): RowSelectionLine[] {
  const byRow = new Map<number, { sortKey: number; text: string }[]>();
  const seenCouches = new Set<string>();

  for (const id of seats) {
    const { row, column } = parseSeatId(id);
    if (row === COUCH_ROW) {
      const [start, end] = couchPairFor(column);
      const key = `${row}:${start}`;
      if (seenCouches.has(key)) continue;
      seenCouches.add(key);
      const list = byRow.get(row) ?? [];
      list.push({ sortKey: start, text: `${start}-${end}` });
      byRow.set(row, list);
    } else {
      const list = byRow.get(row) ?? [];
      list.push({ sortKey: column, text: String(column) });
      byRow.set(row, list);
    }
  }

  return [...byRow.entries()]
    .sort((a, b) => a[0] - b[0])
    .map(([row, items]) => ({
      row,
      text: items
        .sort((a, b) => a.sortKey - b.sortKey)
        .map((i) => i.text)
        .join(', '),
    }));
}

const ISO_DATE_PATTERN = /^\d{4}-\d{2}-\d{2}$/;

export function formatIso(date: Date): string {
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, '0');
  const day = String(date.getDate()).padStart(2, '0');
  return `${year}-${month}-${day}`;
}

export function isoToday(): string {
  return formatIso(new Date());
}

export function parseIso(value: string): Date | null {
  const match = ISO_DATE_PATTERN.exec(value);
  if (!match) return null;
  const [year, month, day] = value.split('-').map(Number);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) {
    return null;
  }
  return date;
}

export function addDays(date: Date, days: number): Date {
  const result = new Date(date);
  result.setDate(result.getDate() + days);
  return result;
}

export function weekdayName(date: Date): string {
  return date.toLocaleDateString('en-US', { weekday: 'long' });
}

export function monthShort(date: Date): string {
  return date.toLocaleDateString('en-US', { month: 'short' });
}

/** `<Weekday> <D> <Mon> <HH:mm>`, e.g. "Tuesday 15 Sep 16:00". */
export function formatShowDate(isoDate: string, time: string): string {
  const date = parseIso(isoDate);
  if (!date) return '';
  return `${weekdayName(date)} ${date.getDate()} ${monthShort(date)} ${time}`;
}

/** Resolves the day shown on the movie list: missing, invalid or past dates fall back to today. */
export function resolveSelectedDate(raw: string | null, todayIso: string): string {
  if (!raw) return todayIso;
  if (!parseIso(raw)) return todayIso;
  if (raw < todayIso) return todayIso;
  return raw;
}

import { couchPairs, isAccessible, seatId, TOTAL_ROWS } from './seat.util';

export interface SeatCellVm {
  kind: 'seat';
  row: number;
  column: number;
  id: string;
  accessible: boolean;
  gridColumn: number;
}

export interface CouchCellVm {
  kind: 'couch';
  row: number;
  columnStart: number;
  columnEnd: number;
  id1: string;
  id2: string;
  gridColumnStart: number;
  gridColumnEnd: number;
}

export type CellVm = SeatCellVm | CouchCellVm;

export interface RowVm {
  row: number;
  blockA: CellVm[];
  blockB: CellVm[];
  blockC: CellVm[];
}

/**
 * Maps a seat column (1-24) to its CSS grid track. Track layout:
 * 1 = left row label, 2-5 = columns 1-4, 6 = aisle, 7-22 = columns 5-20,
 * 23 = aisle, 24-27 = columns 21-24, 28 = right row label.
 */
export function gridTrack(column: number): number {
  if (column <= 4) return column + 1;
  if (column <= 20) return column - 5 + 7;
  return column - 21 + 24;
}

function makeSeatCell(row: number, column: number): SeatCellVm {
  return {
    kind: 'seat',
    row,
    column,
    id: seatId(row, column),
    accessible: isAccessible(row, column),
    gridColumn: gridTrack(column),
  };
}

function makeCouchCell(row: number, start: number, end: number): CouchCellVm {
  return {
    kind: 'couch',
    row,
    columnStart: start,
    columnEnd: end,
    id1: seatId(row, start),
    id2: seatId(row, end),
    gridColumnStart: gridTrack(start),
    gridColumnEnd: gridTrack(end) + 1,
  };
}

function buildAuditoriumLayout(): RowVm[] {
  const rows: RowVm[] = [];

  for (let row = 1; row <= 14; row++) {
    const blockA: CellVm[] = [];
    if (row >= 11) {
      for (let column = 1; column <= 4; column++) {
        blockA.push(makeSeatCell(row, column));
      }
    }

    const blockB: CellVm[] = [];
    for (let column = 5; column <= 20; column++) {
      blockB.push(makeSeatCell(row, column));
    }

    const blockC: CellVm[] = [];
    for (let column = 21; column <= 24; column++) {
      blockC.push(makeSeatCell(row, column));
    }

    rows.push({ row, blockA, blockB, blockC });
  }

  const pairs = couchPairs();
  rows.push({
    row: TOTAL_ROWS,
    blockA: pairs.filter(([start]) => start <= 4).map(([start, end]) => makeCouchCell(TOTAL_ROWS, start, end)),
    blockB: pairs.filter(([start]) => start >= 5 && start <= 19).map(([start, end]) => makeCouchCell(TOTAL_ROWS, start, end)),
    blockC: pairs.filter(([start]) => start >= 21).map(([start, end]) => makeCouchCell(TOTAL_ROWS, start, end)),
  });

  return rows;
}

export const AUDITORIUM_LAYOUT: readonly RowVm[] = buildAuditoriumLayout();

import { HttpClient, HttpParams } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { Movie } from '../models/movie.model';
import { Reservation, ReservationRequest } from '../models/reservation.model';
import { Screening } from '../models/screening.model';

const BASE_URL = 'http://localhost:3000';

@Injectable({ providedIn: 'root' })
export class ApiService {
  private readonly http = inject(HttpClient);

  getMovies(): Observable<Movie[]> {
    return this.http.get<Movie[]>(`${BASE_URL}/movies`);
  }

  getMovie(id: number): Observable<Movie> {
    return this.http.get<Movie>(`${BASE_URL}/movies/${id}`);
  }

  getScreeningsByDate(date: string): Observable<Screening[]> {
    return this.http.get<Screening[]>(`${BASE_URL}/screenings`, { params: new HttpParams().set('date', date) });
  }

  getScreening(id: number): Observable<Screening> {
    return this.http.get<Screening>(`${BASE_URL}/screenings/${id}`);
  }

  createReservation(payload: ReservationRequest): Observable<Reservation> {
    return this.http.post<Reservation>(`${BASE_URL}/reservations`, payload);
  }
}

import { Injectable, signal } from '@angular/core';
import { Booking, BookingForm, emptyBooking } from '../models/booking.model';
import { MAX_SEATS_PER_BOOKING } from '../utils/seat.util';

const STORAGE_KEY = 'cinescope.booking';

export type ToggleResult = 'added' | 'removed' | 'limit';

@Injectable({ providedIn: 'root' })
export class BookingService {
  private readonly _booking = signal<Booking | null>(loadFromStorage());
  readonly booking = this._booking.asReadonly();

  private persist(booking: Booking | null): void {
    this._booking.set(booking);
    if (booking) {
      sessionStorage.setItem(STORAGE_KEY, JSON.stringify(booking));
    } else {
      sessionStorage.removeItem(STORAGE_KEY);
    }
  }

  /**
   * Keeps the in-progress booking when it already belongs to this screening and is unpaid;
   * otherwise starts a fresh, empty booking for it.
   */
  ensureForScreening(screeningId: number): void {
    const current = this._booking();
    if (!current || current.paid || current.screeningId !== screeningId) {
      this.persist(emptyBooking(screeningId));
    }
  }

  isActiveFor(screeningId: number): boolean {
    const booking = this._booking();
    return !!booking && !booking.paid && booking.screeningId === screeningId && booking.seats.length > 0;
  }

  isPaid(): boolean {
    return this._booking()?.paid ?? false;
  }

  /** Toggles a seat (or both identifiers of a couch) as one unit. */
  toggleSeats(identifiers: string[]): ToggleResult {
    const booking = this._booking();
    if (!booking) return 'removed';

    const allSelected = identifiers.every((id) => booking.seats.includes(id));
    if (allSelected) {
      this.persist({ ...booking, seats: booking.seats.filter((s) => !identifiers.includes(s)) });
      return 'removed';
    }

    if (booking.seats.length + identifiers.length > MAX_SEATS_PER_BOOKING) {
      return 'limit';
    }

    this.persist({ ...booking, seats: [...booking.seats, ...identifiers] });
    return 'added';
  }

  removeSeats(identifiers: string[]): void {
    const booking = this._booking();
    if (!booking) return;
    this.persist({ ...booking, seats: booking.seats.filter((s) => !identifiers.includes(s)) });
  }

  updateForm(partial: Partial<BookingForm>): void {
    const booking = this._booking();
    if (!booking) return;
    this.persist({ ...booking, form: { ...booking.form, ...partial } });
  }

  markPaid(email: string): void {
    const booking = this._booking();
    if (!booking) return;
    this.persist({ ...booking, paid: true, customerEmail: email });
  }

  clear(): void {
    this.persist(null);
  }
}

function loadFromStorage(): Booking | null {
  const raw = sessionStorage.getItem(STORAGE_KEY);
  if (!raw) return null;
  try {
    return JSON.parse(raw) as Booking;
  } catch {
    return null;
  }
}

import { Component, inject } from '@angular/core';
